import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.Dk8PTAaz.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"en/guide/introduction.md","lastUpdated":1788616892000}'),i={name:"en/guide/introduction.md"};function n(s,t,d,l,u,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><code>@meng-xi/unix-router</code> is a routing library for <strong>uni-app x</strong>, with an API style that mirrors <strong>vue-router 4</strong>. It is built on uni-app x&#39;s <strong>static page model</strong> (<code>.uvue</code> pages + <code>pages.json</code> registration + <code>uni.*</code> native navigation) and written in <strong>UTS</strong> (<code>.uts</code>).</p><h2 id="why-you-need-it" tabindex="-1">Why You Need It <a class="header-anchor" href="#why-you-need-it" aria-label="Permalink to &quot;Why You Need It&quot;">​</a></h2><p>uni-app x natively provides <code>uni.navigateTo / redirectTo / reLaunch / navigateBack / switchTab</code>. As pages grow, using these directly has obvious pain points:</p><ul><li><strong>No route table</strong>: page paths are scattered with no centralized management and no named routes or type hints.</li><li><strong>No guards</strong>: you cannot run login checks or analytics before navigation.</li><li><strong>No route state</strong>: there is no unified reactive <code>currentRoute</code>, making it hard to track the current page in the Composition API.</li><li><strong>Cumbersome parameter passing</strong>: object parameters are hard to pass across pages, and query parsing has to be handwritten.</li></ul><p>unix-router smooths over these differences with an API set consistent with vue-router.</p><h2 id="who-is-it-for" tabindex="-1">Who Is It For <a class="header-anchor" href="#who-is-it-for" aria-label="Permalink to &quot;Who Is It For&quot;">​</a></h2><ul><li><strong>Migrating from uni-app (Vue 3) to uni-app x</strong>: get familiar quickly with a routing style you already know.</li><li><strong>Pages have grown and need centralized navigation &amp; auth</strong>: a route table plus guards make the flow clear and controllable.</li><li><strong>You want consistent routing behavior across web / Mini Program / App</strong>: one API spans all platforms.</li></ul><h2 id="how-this-guide-takes-you-from-beginner-to-master" tabindex="-1">How This Guide Takes You from Beginner to Master <a class="header-anchor" href="#how-this-guide-takes-you-from-beginner-to-master" aria-label="Permalink to &quot;How This Guide Takes You from Beginner to Master&quot;">​</a></h2><p>The docs are organized progressively. Read them in order:</p><table tabindex="0"><thead><tr><th>Stage</th><th>Topics</th><th>What you&#39;ll master</th></tr></thead><tbody><tr><td>🟢 <strong>Beginner</strong></td><td><a href="./getting-started.html">Quick Start</a> → <a href="./route-config.html">Route Configuration</a> → <a href="./navigation.html">Navigation</a></td><td>Run your first navigation from scratch; understand the route table, four navigation modes, and parameter passing</td></tr><tr><td>🟢 <strong>Beginner</strong></td><td><a href="./../api/use-route.html">Reading the route</a> / <a href="./composables.html">Composables</a></td><td><code>useRouter</code> / <code>useRoute</code> / <code>useLink</code> and their lifecycle interaction</td></tr><tr><td>🟡 <strong>Intermediate</strong></td><td><a href="./guards.html">Route Guards</a> → <a href="./meta.html">Route Meta</a></td><td>Login auth, <code>beforeEnter</code>, cold-start guards, dynamic titles</td></tr><tr><td>🟡 <strong>Intermediate</strong></td><td><a href="./error-handling.html">Error Handling</a> → <a href="./navigation-flow.html">Navigation Flow</a></td><td>Failure detection, global error capture, understanding the internals of a navigation</td></tr><tr><td>🔴 <strong>Master</strong></td><td><a href="./recipes.html">Recipes</a> → <a href="./compatibility.html">Platform Compatibility</a></td><td>Build a complete login + TabBar + detail app with one pattern; master platform differences and common pitfalls</td></tr></tbody></table><blockquote><p><strong>Tip</strong>: the <a href="https://github.com/MengXi-Studio/unix-router/tree/master/packages/playground" target="_blank" rel="noreferrer"><code>packages/playground</code></a> in the repo is a runnable uni-app x project that includes a <code>pages/test</code> self-check page (programmatic PASS/FAIL output). Use it to verify alongside the docs.</p></blockquote><h2 id="capabilities-at-a-glance" tabindex="-1">Capabilities at a Glance <a class="header-anchor" href="#capabilities-at-a-glance" aria-label="Permalink to &quot;Capabilities at a Glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Description</th></tr></thead><tbody><tr><td>Route matching</td><td><code>path</code> / <code>name</code> dual index, string / object / named resolution, strict mode</td></tr><tr><td>Navigation</td><td>push / replace / relaunch / back, auto-detects TabBar</td></tr><tr><td>Guards</td><td>beforeEach / beforeResolve / afterEach / beforeEnter / onBeforeRouteLeave, etc.</td></tr><tr><td>Composition API</td><td>useRouter / useRoute / useLink</td></tr><tr><td>Error system</td><td>RouterError / NavigationFailure / isNavigationFailure</td></tr><tr><td>Extensions</td><td>guardRoute cold-start guard, duplicate-navigation interception, guard redirect + depth limit</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Want to start right away? Go to <a href="./installation.html">Installation</a> or <a href="./getting-started.html">Quick Start</a>.</li><li>Want to understand the design trade-offs? See <a href="./differences.html">Differences from vue-router</a>.</li></ul>',16)])])}const p=e(i,[["render",n]]);export{g as __pageData,p as default};
